INSERT INTO quiz_questions (id, course_id, order_index, question) VALUES ('1bfa7cd0-5afe-5323-9a73-6ab0e9a06efa', 'd6c8c470-31de-552b-9d00-9b2f36414670', 0, 'Роговой слой кожи сравнивают с кирпичной стеной, где «кирпичики» — это корнеоциты. А что выступает в роли «цемента», скрепляющего их и позволяющего коже удерживать влагу?');
